public class Bridge:IDisposable {
 Process process;int next;object sync=new object();Dictionary<int,TaskCompletionSource<object>> calls=new Dictionary<int,TaskCompletionSource<object>>();public Action<Dictionary<string,object>> Event;
 public bool Started{get{return process!=null&&!process.HasExited;}}
 public void Start(){if(Started)return;if(!File.Exists(Paths.CorePython))throw new Exception("请先在配置中下载并配置服务运行环境。");var p=new ProcessStartInfo(Paths.CorePython,"-B -u \""+Path.Combine(Paths.App,"native_bridge.py")+"\""){WorkingDirectory=Paths.App,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};p.EnvironmentVariables["PYTHONIOENCODING"]="utf8";p.EnvironmentVariables["PYTHONUTF8"]="1";Directory.CreateDirectory(Path.Combine(Paths.Data,"cache"));p.EnvironmentVariables["TEMP"]=Path.Combine(Paths.Data,"cache");p.EnvironmentVariables["TMP"]=Path.Combine(Paths.Data,"cache");p.EnvironmentVariables["PATH"]=Path.GetDirectoryName(Paths.CorePython)+";"+Environment.GetEnvironmentVariable("PATH");process=new Process{StartInfo=p,EnableRaisingEvents=true};process.OutputDataReceived+=(s,e)=>{if(e.Data==null)return;try{var d=Paths.Obj(Paths.Json.DeserializeObject(e.Data));if(d.ContainsKey("event")){if(Event!=null)Event(d);return;}int id=Convert.ToInt32(d["id"]);TaskCompletionSource<object> t;lock(sync){if(!calls.TryGetValue(id,out t))return;calls.Remove(id);}if(Convert.ToBoolean(d["ok"]))t.TrySetResult(d["result"]);else t.TrySetException(new Exception(Paths.S(d,"error")));}catch(Exception ex){Paths.Log("bridge parse: "+ex.Message);}};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)Paths.Log(e.Data);};process.Exited+=(s,e)=>{lock(sync){foreach(var t in calls.Values)t.TrySetException(new Exception("引擎服务已退出，请查看日志。"));calls.Clear();}};process.Start();process.StandardInput.AutoFlush=true;process.BeginOutputReadLine();process.BeginErrorReadLine();}
 public Task<object> Call(string cmd,Dictionary<string,object> args=null){Start();var d=args??new Dictionary<string,object>();var t=new TaskCompletionSource<object>();lock(sync){int id=++next;d["id"]=id;d["cmd"]=cmd;calls[id]=t;process.StandardInput.WriteLine(Paths.Json.Serialize(d));}return t.Task;}
 public void Dispose(){if(!Started)return;try{process.StandardInput.Close();if(!process.WaitForExit(2500))process.Kill();}catch{}}
}
