 void Error(Exception ex){Paths.Log(ex.ToString());MessageBox.Show(this,ex.Message,"任务失败",MessageBoxButton.OK,MessageBoxImage.Error);}
 async Task Run(string label,Func<Task> action){if(busy){MessageBox.Show(this,busyLabel+"正在执行。");return;}busy=true;RefreshDeleteButton();busyLabel=label;config.IsEnabled=false;status.Text=label;try{await action();status.Text=label+"完成";}catch(Exception ex){status.Text=label+"失败";Error(ex);}finally{busy=false;config.IsEnabled=true;RefreshDeleteButton();}}
 async Task LoadCatalog(){await Run("载入音频库",async()=>ApplyCatalog(Paths.Obj(await Service.Call("catalog"))));}
 void ApplyCatalog(Dictionary<string,object> data){loading=true;var old=selected;selected=new HashSet<string>(Paths.Arr(data["selected"]).Select(x=>x.ToString()));var outputs=new HashSet<string>(Paths.Arr(data["outputs"]).Select(x=>x.ToString()));all=Paths.Arr(data["rows"]).Select(x=>new Row{Raw=Paths.Obj(x)}).ToList();foreach(var r in all){r.Selected=selected.Contains(r.Key);r.Generated=outputs.Contains(r.Key);r.SelectionChanged=SelectionChanged;}game.Text=Paths.S(data,"game");dark=Paths.S(data,"theme")=="dark";Theme();loading=false;BuildChapters();}
 void SelectionChanged(Row r){if(loading)return;if(r.Selected)selected.Add(r.Key);else selected.Remove(r.Key);status.Text="已勾选 "+selected.Count+" 条";selectionTimer.Stop();selectionTimer.Start();RefreshChecks();}
 void ChangeTab(string value){if(tab==value)return;tab=value;category="";actor="";page=0;UpdateTabs();BuildChapters();}
 List<Row> Filtered(){return all.Where(r=>r.Tab==tab&&r.Chapter==category&&r.Actor==actor).ToList();}
 void BuildChapters(){var groups=all.Where(r=>r.Tab==tab).GroupBy(r=>r.Chapter).Select(g=>new Group{Id=g.Key,Label=g.Key,Rows=g.ToList()}).ToList();if(!groups.Any(g=>g.Id==category))category=groups.Count>0?groups[0].Id:"";FillGroups(chapters,groups,category);BuildActors();}
 void BuildActors(){var groups=all.Where(r=>r.Tab==tab&&r.Chapter==category).GroupBy(r=>r.Actor).Select(g=>new Group{Id=g.Key,Label=g.First().ActorLabel,Rows=g.ToList()}).OrderBy(g=>g.Label,StringComparer.Ordinal).ToList();if(!groups.Any(g=>g.Id==actor))actor=groups.Count>0?groups[0].Id:"";FillGroups(actors,groups,actor);Render();}
 void FillGroups(ListBox list,List<Group> groups,string active){list.Items.Clear();foreach(var g in groups){var panel=new DockPanel{Margin=new Thickness(0,4,0,4)};var check=new CheckBox{IsThreeState=true,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(2,2,8,2),Tag=g};check.IsChecked=GroupState(g);check.Click+=(s,e)=>{var box=(CheckBox)s;var group=(Group)box.Tag;bool value=group.Rows.Any(r=>!selected.Contains(r.Key));loading=true;foreach(var r in group.Rows){r.Selected=value;if(value)selected.Add(r.Key);else selected.Remove(r.Key);}loading=false;selectionTimer.Stop();selectionTimer.Start();RefreshChecks();status.Text="已勾选 "+selected.Count+" 条";e.Handled=true;};panel.Children.Add(check);var label=Label(g.Label);label.TextTrimming=TextTrimming.CharacterEllipsis;panel.Children.Add(label);var item=new ListBoxItem{Content=panel,Tag=g,Padding=new Thickness(4),HorizontalContentAlignment=HorizontalAlignment.Stretch};list.Items.Add(item);if(g.Id==active)list.SelectedItem=item;}}
 bool? GroupState(Group g){int n=g.Rows.Count(r=>selected.Contains(r.Key));return n==0?false:n==g.Rows.Count?(bool?)true:null;}
 void RefreshChecks(){RefreshDeleteButton();foreach(ListBox list in new[]{chapters,actors})foreach(ListBoxItem item in list.Items){var p=item.Content as DockPanel;var c=p.Children[0] as CheckBox;c.IsChecked=GroupState((Group)item.Tag);}}
 void RefreshDeleteButton(){if(deleteSelected!=null)deleteSelected.IsEnabled=!busy&&all.Any(r=>r.Generated&&selected.Contains(r.Key));}
 void Render(){RefreshDeleteButton();var rows=Filtered();int max=Math.Max(1,(rows.Count+59)/60);page=Math.Max(0,Math.Min(page,max-1));grid.ItemsSource=rows.Skip(page*60).Take(60).ToList();pageText.Text=(page+1)+" / "+max;}
 async Task Validate(bool save=false){try{var d=Paths.Obj(await Service.Call("validate",new Dictionary<string,object>{{"path",game.Text}}));pathStatus.Text=Paths.S(d,"text");pathStatus.Foreground=Convert.ToBoolean(d["valid"])?Brushes.SeaGreen:Brushes.IndianRed;if(save&&Convert.ToBoolean(d["valid"]))await Service.Call("set_game",new Dictionary<string,object>{{"path",game.Text}});}catch(Exception ex){pathStatus.Text=ex.Message;}}
 async Task Scan(){await Run("扫描本地音频",async()=>{ApplyCatalog(Paths.Obj(await Service.Call("scan",new Dictionary<string,object>{{"path",game.Text}})));await Validate();});}
 async Task Generate(List<Row> rows){if(rows.Count==0){MessageBox.Show(this,"请勾选需要生成的台词。");return;}await Run("生成中文音频",async()=>{var result=Paths.Obj(await Service.Call("generate",new Dictionary<string,object>{{"keys",rows.Select(r=>r.Key).ToArray()}}));var failures=Paths.Arr(result["failed"]);if(failures.Length>0)throw new Exception(failures.Length+" 条生成失败："+Paths.S(Paths.Obj(failures[0]),"error"));});}
 async Task Delete(List<Row> rows){rows=rows.Where(r=>r.Generated).ToList();if(rows.Count==0)return;if(busy){MessageBox.Show(this,"当前任务执行中，请稍后删除。");return;}if(MessageBox.Show(this,"删除勾选的 "+rows.Count+" 条中文音频？删除后可以重新生成。","删除中文音频",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;await Run("删除中文音频",async()=>{await Service.Call("delete",new Dictionary<string,object>{{"keys",rows.Select(r=>r.Key).ToArray()}});foreach(var r in rows)r.Generated=false;});}
 async void RowClick(object sender,RoutedEventArgs e){var button=e.OriginalSource as Button;if(button==null)return;var r=button.DataContext as Row;if(r==null)return;string cmd=button.Tag as string;if(cmd=="生成")await Generate(new List<Row>{r});else if(cmd=="删除")await Delete(new List<Row>{r});else if(cmd=="试听"){var menu=new ContextMenu();var cn=new MenuItem{Header="试听中文",IsEnabled=r.Generated};cn.Click+=async(s,a)=>await Play(r,true);var ko=new MenuItem{Header="试听游戏原声",IsEnabled=r.HasOriginal};ko.Click+=async(s,a)=>await Play(r,false);var stop=new MenuItem{Header="停止播放"};stop.Click+=async(s,a)=>{try{await Service.Call("stop");}catch(Exception ex){Error(ex);}};menu.Items.Add(cn);menu.Items.Add(ko);menu.Items.Add(stop);button.ContextMenu=menu;menu.IsOpen=true;}e.Handled=true;}
 async Task Play(Row r,bool chinese){try{await Service.Call("play",new Dictionary<string,object>{{"key",r.Key},{"chinese",chinese}});}catch(Exception ex){Error(ex);}}
 async Task Connect(bool value){if(connecting)return;if(value&&connected)return;connecting=true;connect.IsEnabled=false;disconnect.IsEnabled=false;try{var request=Service.Call(value?"connect":"disconnect");if(await Task.WhenAny(request,Task.Delay(60000))!=request){Service.Dispose();Service=new Bridge();Service.Event=evt=>Dispatcher.BeginInvoke(new Action(()=>HandleEvent(evt)));throw new TimeoutException("连接操作超时，已释放后台服务，可以重新连接。");}var d=Paths.Obj(await request);connected=Convert.ToBoolean(d["connected"]);runtime.Text=connected?"已连接游戏 · "+Paths.S(d,"count")+" 条可替换中文":"游戏未连接";}catch(Exception ex){connected=false;connecting=false;connect.IsEnabled=true;connect.Content="连接游戏";disconnect.IsEnabled=false;runtime.Text="连接失败，可重新连接";Error(ex);}finally{connecting=false;connect.IsEnabled=!connected;disconnect.IsEnabled=connected;connect.Content=connected?"已连接游戏":"连接游戏";}}
 void HandleEvent(Dictionary<string,object> d){string ev=Paths.S(d,"event");if(ev=="status")status.Text=Paths.S(d,"text");else if(ev=="runtime"){runtime.Text=Paths.S(d,"text");if(runtime.Text.Contains("已断开")||runtime.Text.Contains("连接已断开")){connected=false;connect.IsEnabled=true;connect.Content="连接游戏";disconnect.IsEnabled=false;}}else if(ev=="generated"){var r=all.FirstOrDefault(x=>x.Key==Paths.S(d,"key"));if(r!=null)r.Generated=true;}else if(ev=="rowerror")status.Text=Paths.S(d,"key")+" · "+Paths.S(d,"text");else if(ev=="progress"){double total=Convert.ToDouble(d["total"]),done=Convert.ToDouble(d["done"]),elapsed=Convert.ToDouble(d["elapsed"]);progress.Maximum=Math.Max(1,total);progress.Value=done;string eta=done>0?TimeSpan.FromSeconds(elapsed/done*Math.Max(0,total-done)).ToString(@"hh\:mm\:ss"):"—";counts.Text="本次总数 "+total+" · 当前 "+Paths.S(d,"current")+"/"+total+" · 已生成 "+Paths.S(d,"success")+" · 预计剩余 "+eta;}}
}
public class ConfigWindow:Window {
 TextBlock[] labels=new TextBlock[4],details=new TextBlock[4],amounts=new TextBlock[4];ProgressBar[] bars=new ProgressBar[4];Button[] downloads=new Button[4],deletes=new Button[4];bool[] active=new bool[4];bool running{get{return active.Any(x=>x);}}CancellationTokenSource[] cancellations=new CancellationTokenSource[4];Button cancel;Action release;static long?[] sizeCache=new long?[4];bool measuring;
 public ConfigWindow(bool dark,Action releaseService=null){release=releaseService;Title="084CN · 配置";Width=800;Height=490;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterOwner;FontFamily=new FontFamily("Microsoft YaHei UI");WindowChrome.SetWindowChrome(this,new WindowChrome{CaptionHeight=35,ResizeBorderThickness=new Thickness(0),CornerRadius=new CornerRadius(24),GlassFrameThickness=new Thickness(0)});Background=(Brush)new BrushConverter().ConvertFromString(dark?"#141821":"#F3F5FA");Foreground=dark?Brushes.WhiteSmoke:Brushes.Black;
 var border=new Border{Margin=new Thickness(12),Padding=new Thickness(24),CornerRadius=new CornerRadius(24),Background=(Brush)new BrushConverter().ConvertFromString(dark?"#1E2430":"#FFFFFF")};Content=border;var panel=new StackPanel();border.Child=panel;panel.Children.Add(new TextBlock{Text="引擎与音色配置",FontSize=23,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,0,16)});
 for(int i=0;i<4;i++){int id=i;var row=new Grid{Margin=new Thickness(0,0,0,12)};row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var content=new StackPanel{Margin=new Thickness(0,0,12,0)};row.Children.Add(content);labels[i]=new TextBlock{FontSize=14,FontWeight=FontWeights.SemiBold};content.Children.Add(labels[i]);details[i]=new TextBlock{FontSize=11,Margin=new Thickness(0,3,0,4),TextTrimming=TextTrimming.CharacterEllipsis};content.Children.Add(details[i]);var progress=new Grid();progress.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});progress.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(165)});bars[i]=new ProgressBar{Height=8,Maximum=100,VerticalAlignment=VerticalAlignment.Center};progress.Children.Add(bars[i]);amounts[i]=new TextBlock{FontSize=11,Text="— / —",Margin=new Thickness(10,0,0,0),TextAlignment=TextAlignment.Right};Grid.SetColumn(amounts[i],1);progress.Children.Add(amounts[i]);content.Children.Add(progress);downloads[i]=Button("下载",async(s,e)=>await Download(id));deletes[i]=Button("删除",async(s,e)=>await Delete(id));Grid.SetColumn(downloads[i],1);Grid.SetColumn(deletes[i],2);row.Children.Add(downloads[i]);row.Children.Add(deletes[i]);panel.Children.Add(row);}
 var footer=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,12,0,0)};footer.Children.Add(Button("打开配置文件夹",(s,e)=>{Directory.CreateDirectory(Paths.Data);Process.Start(Paths.Data);}));cancel=Button("取消下载",(s,e)=>{foreach(var token in cancellations)if(token!=null)token.Cancel();});cancel.IsEnabled=false;footer.Children.Add(cancel);footer.Children.Add(Button("关闭",(s,e)=>Close()));panel.Children.Add(footer);
 Loaded+=(s,e)=>{if(Owner!=null)foreach(object key in Owner.Resources.Keys)Resources[key]=Owner.Resources[key];Refresh();MeasureSizes();};Closing+=(s,e)=>{if(running){e.Cancel=true;foreach(var token in cancellations)if(token!=null)token.Cancel();}};
 }
 Button Button(string text,RoutedEventHandler action){var b=new Button{Content=text,Padding=new Thickness(13,8,13,8),Margin=new Thickness(3),VerticalAlignment=VerticalAlignment.Center};b.Click+=action;return b;}
 void Refresh(){for(int i=0;i<4;i++){bool ready=NativeInstaller.ComponentReady(i);labels[i].Text=NativeInstaller.ComponentNames[i]+" · "+(ready?"已部署":"未部署")+" · 需占用约 "+NativeInstaller.FormatBytes(NativeInstaller.RequiredSize(i));downloads[i].IsEnabled=!active[i]&&!ready;deletes[i].IsEnabled=!active[i]&&NativeInstaller.ComponentPaths(i).Any(p=>File.Exists(p)||Directory.Exists(p));if(!active[i]){details[i].Text=ready?"可直接使用":"等待下载";bars[i].IsIndeterminate=false;bars[i].Value=ready?100:0;amounts[i].Text=ready?(sizeCache[i].HasValue?NativeInstaller.FormatBytes(sizeCache[i].Value)+" / "+NativeInstaller.FormatBytes(sizeCache[i].Value):"已部署"):"0 / —";}}}
 async void MeasureSizes(){if(measuring)return;measuring=true;try{for(int i=0;i<4;i++){int id=i;if(sizeCache[id].HasValue)continue;long bytes=await Task.Run(()=>NativeInstaller.ComponentSize(id));sizeCache[id]=bytes;if(IsVisible&&!running)Refresh();}}catch(Exception ex){Paths.Log("Component size: "+ex.Message);}finally{measuring=false;}}
 async Task Download(int id){if(active[id])return;if(!running&&release!=null)release();active[id]=true;var cancellation=new CancellationTokenSource();cancellations[id]=cancellation;Refresh();cancel.IsEnabled=true;try{await Task.Run(()=>NativeInstaller.InstallComponent(id,(message,value)=>Dispatcher.BeginInvoke(new Action(()=>{details[id].Text=message.Replace('\n',' ');bars[id].IsIndeterminate=value<0;if(value>=0)bars[id].Value=value;var match=System.Text.RegularExpressions.Regex.Match(message,@"([\d.]+\s*/\s*[\d.]+\s*MB)");if(match.Success){amounts[id].Text=match.Value;amounts[id].ToolTip="当前下载文件：已下载 / 总大小";}else if(value<0)amounts[id].Text="安装 / 校验中";})),cancellation.Token));}catch(OperationCanceledException){details[id].Text="已取消，可继续下载";}catch(Exception ex){MessageBox.Show(this,ex.Message,"配置失败");Paths.Log(ex.ToString());}finally{active[id]=false;cancellations[id]=null;cancellation.Dispose();cancel.IsEnabled=cancellations.Any(t=>t!=null);sizeCache[id]=null;Refresh();MeasureSizes();}}
 async Task Delete(int id){if(active[id])return;if(MessageBox.Show(this,"删除“"+NativeInstaller.ComponentNames[id]+"”？删除后可重新下载。","删除组件",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;if(!running&&release!=null)release();active[id]=true;Refresh();try{await Task.Run(()=>NativeInstaller.DeleteComponent(id));}catch(Exception ex){MessageBox.Show(this,ex.Message,"删除失败");}finally{active[id]=false;sizeCache[id]=null;Refresh();MeasureSizes();}}
}

public class Installer {
 public static string Status(){return "服务运行环境："+(NativeInstaller.CoreReady()?"已部署":"待下载")+"\nIndexTTS2："+(NativeInstaller.ModelReady()?"已部署":"待下载")+"\n但丁音色："+(File.Exists(Path.Combine(Paths.Engines,"voices/dante.wav"))?"已部署":"待下载")+"\n旁白音色："+(File.Exists(Path.Combine(Paths.Engines,"voices/narrator.wav"))?"已部署":"待下载")+"\n\n组件统一保存在“Engines”目录，用户无需安装 Python。";}
 public static Task Install(Action<string,double> report,CancellationToken token){return Task.Run(async()=>{Directory.CreateDirectory(Paths.Engines);await NativeInstaller.Install(report,token);},token);}
}
public static class Entry {
 [STAThread]public static int Main(string[] args){try{ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;Directory.CreateDirectory(Paths.Data);Directory.CreateDirectory(Paths.Output);Directory.CreateDirectory(Paths.Engines);if(args.Contains("--cold-index-test")){NativeInstaller.ColdIndexTest().GetAwaiter().GetResult();return 0;}if(args.Contains("--cold-runtime-test")){NativeInstaller.ColdRuntimeTest().GetAwaiter().GetResult();return 0;}if(args.Contains("--download-test")){NativeInstaller.SelfTest().GetAwaiter().GetResult();return 0;}if(args.Contains("--integration-test")){using(var bridge=new Bridge()){var before=Paths.Obj(bridge.Call("catalog").GetAwaiter().GetResult());var result=Paths.Obj(bridge.Call("generate",new Dictionary<string,object>{{"keys",new[]{"unvoiced-S202A-2"}}}).GetAwaiter().GetResult());if(Paths.Arr(result["failed"]).Length!=0)throw new Exception(Paths.Json.Serialize(result["failed"]));bridge.Call("play",new Dictionary<string,object>{{"key","unvoiced-S202A-2"},{"chinese",true}}).GetAwaiter().GetResult();System.Threading.Thread.Sleep(250);bridge.Call("stop").GetAwaiter().GetResult();bridge.Call("play",new Dictionary<string,object>{{"key","S202A-01"},{"chinese",false}}).GetAwaiter().GetResult();System.Threading.Thread.Sleep(250);bridge.Call("stop").GetAwaiter().GetResult();File.WriteAllText(Path.Combine(Paths.Data,"native-integration-test.json"),Paths.Json.Serialize(new Dictionary<string,object>{{"generate",true},{"chinese_output",true},{"chinese_play_stream",true},{"original_play_stream",true},{"selected_before",Paths.Arr(before["selected"]).Length},{"listening_acceptance",false}}));return 0;}}if(args.Contains("--backend-test")){using(var bridge=new Bridge()){var task=bridge.Call("catalog");if(!task.Wait(60000))throw new Exception("Backend timeout");var data=Paths.Obj(task.Result);File.WriteAllText(Path.Combine(Paths.Data,"native-backend-test.json"),Paths.Json.Serialize(new Dictionary<string,object>{{"rows",Paths.Arr(data["rows"]).Length},{"selected",Paths.Arr(data["selected"]).Length},{"outputs",Paths.Arr(data["outputs"]).Length},{"theme",Paths.S(data,"theme")}}));return 0;}}var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};var main=new MainWindow{Smoke=args.Contains("--self-test")};app.Run(main);return 0;}catch(Exception ex){Paths.Log(ex.ToString());if(!args.Contains("--self-test")&&!args.Contains("--backend-test")&&!args.Contains("--download-test")&&!args.Contains("--integration-test")&&!args.Contains("--cold-runtime-test")&&!args.Contains("--cold-index-test"))MessageBox.Show(ex.Message,"084CN 启动失败");return 1;}}
}
